<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue'
import {Info,ChevronLeft,ChevronRight,SlidersHorizontal} from 'lucide-vue-next'
import {api} from '../lib/api'
import {friendlyError} from '../lib/format'
import {differences,displaySetting,type SavedLayout} from '../lib/bundleSettings'
import type {MatterDocument} from '../lib/types'
import ManualBookmarks from './ManualBookmarks.vue'
import NumberingSettings from './NumberingSettings.vue'
import NumberPlacementPreview from './NumberPlacementPreview.vue'
import BundlePresetDialog from './BundlePresetDialog.vue'
const props=defineProps<{matterId:string;documents:MatterDocument[];refreshKey:number;disabled:boolean;initialMode?:string;bookmarkPreset?:{documentId:string;sequence:number}}>()
const emit=defineEmits<{modified:[];dirtyChanged:[dirty:boolean];membership:[];build:[];policy:[name:string]}>()
const mode=ref(['Numbering','Edit numbering'].includes(props.initialMode||'')?'numbering':props.initialMode==='Presets'?'map':props.initialMode==='Preview'||props.initialMode==='Cover & sections'?'cover':'map')
const presetsOpen=ref(props.initialMode==='Presets'),settings=ref<SavedLayout|null>(null),saved=ref(''),error=ref(''),notice=ref(''),loading=ref(false),saving=ref(false),drawer=ref(false)
const bookmarksRef=ref<InstanceType<typeof ManualBookmarks>|null>(null),bookmarkDirty=ref(false)
const settingsDirty=computed(()=>!!settings.value&&JSON.stringify(settings.value)!==saved.value)
const dirty=computed(()=>settingsDirty.value||bookmarkDirty.value)
const included=computed(()=>props.documents.filter(d=>d.bundle_included))
const overrides=computed(()=>settings.value?differences(settings.value,settings.value.applied):[])
const mapKey=ref(0)
const volume=ref(1),indexPage=ref(1)
type Preview={input_snapshot:string;source_pages:number;generated_pages:number;combined_pages:number;included_documents:number;selected_volume:number;selected_index_page:number;volumes:Array<{number:number;index_pages:number;cover_pages:number;page_count:number}>;pages:Array<{kind:string;physical_page:number;image:string;text:string}>}
const preview=ref<Preview|null>(null),previewError=ref(''),previewLoading=ref(false)
let sequence=0,loadSequence=0,timer:ReturnType<typeof setTimeout>|undefined,alive=true
watch(dirty,value=>emit('dirtyChanged',value),{immediate:true})
async function load(force=false){const call=++loadSequence;loading.value=true;error.value='';try{const value=await api<SavedLayout>(`/matters/${props.matterId}/bundle-settings`);if(!alive||call!==loadSequence)return;if(!dirty.value||force){saved.value=JSON.stringify(value);settings.value=value} }catch(e){if(alive&&call===loadSequence)error.value=friendlyError(e)}finally{if(alive&&call===loadSequence)loading.value=false}}
watch(()=>[props.matterId,props.refreshKey],()=>{sequence++;preview.value=null;void load()},{immediate:true})
async function refresh(){clearTimeout(timer);const call=++sequence;preview.value=null;previewError.value='';if(!settings.value||props.disabled){previewLoading.value=false;return}previewLoading.value=true;const draft=settings.value;try{const result=await api<Preview>(`/matters/${props.matterId}/front-matter-preview`,'POST',{max_pages_per_volume:draft.max_pages_per_volume,keep_groups_intact:draft.keep_groups_intact,output_marks:draft.output_marks,volume:volume.value,index_page:indexPage.value});if(alive&&call===sequence){preview.value=result;}}catch(e){if(alive&&call===sequence)previewError.value=friendlyError(e)}finally{if(alive&&call===sequence)previewLoading.value=false}}
watch(()=>[JSON.stringify(settings.value),volume.value,indexPage.value,props.refreshKey,props.disabled],()=>{sequence++;preview.value=null;previewError.value='';previewLoading.value=!!settings.value&&!props.disabled;clearTimeout(timer);timer=setTimeout(()=>void refresh(),220)})
async function saveDraft(){if(bookmarkDirty.value){if(!(await bookmarksRef.value?.saveDraft()))return false;const latest=await api<SavedLayout>(`/matters/${props.matterId}/bundle-settings`);if(settings.value)settings.value.input_snapshot=latest.input_snapshot;}if(!settings.value||saving.value||props.disabled)return false;if(!dirty.value)return true;saving.value=true;error.value='';notice.value='';const draft=JSON.stringify(settings.value);try{const d=JSON.parse(draft) as SavedLayout;const result=await api<SavedLayout>(`/matters/${props.matterId}/bundle-settings`,'PUT',{max_pages_per_volume:d.max_pages_per_volume,keep_groups_intact:d.keep_groups_intact,output_marks:d.output_marks,expected_snapshot:d.input_snapshot});if(!alive)return false;saved.value=JSON.stringify(result);if(JSON.stringify(settings.value)===draft)settings.value=result;else if(settings.value)settings.value.input_snapshot=result.input_snapshot;notice.value='Settings applied. The next build uses this layout.';emit('modified');return !dirty.value}catch(e){if(alive)error.value=friendlyError(e);return false}finally{if(alive)saving.value=false}}
function discard(){bookmarksRef.value?.discard();if(saved.value)settings.value=JSON.parse(saved.value);error.value='';notice.value='Changes cancelled.'}
async function applied(){presetsOpen.value=false;await load(true);emit('modified');notice.value='Preset applied. Review the current layout and any retained overrides.'}
function selectMode(value:string){mode.value=value;drawer.value=false;notice.value=''}
defineExpose({saveDraft,discard,showBookmarks:()=>selectMode('bookmarks')})
onBeforeUnmount(()=>{alive=false;sequence++;loadSequence++;clearTimeout(timer);emit('dirtyChanged',false)})
</script>
<template>
<section class="bundle-structure" :data-mode="mode" aria-label="Bundle structure workspace">
 <header class="structure-heading"><div><h1>{{mode==='numbering'?'Numbering & navigation':mode==='bookmarks'?'Bookmark destinations':mode==='cover'?'Cover & index preview':mode==='volumes'?'Volume planning':'Index & bookmarks'}}</h1><p v-if="preview">{{preview.included_documents}} included documents · {{preview.source_pages}} source + {{preview.generated_pages}} generated = {{preview.combined_pages}} physical pages</p><p v-else>{{included.length}} included documents · {{included.reduce((n,d)=>n+d.page_count,0)}} source pages · {{previewLoading?'Recalculating current inputs…':'Current working revisions'}}</p></div><button v-if="mode==='cover'||mode==='volumes'||mode==='numbering'" class="membership-button primary" :disabled="disabled||saving||!dirty" @click="saveDraft">{{saving?'Applying…':error?'Retry settings':'Apply settings'}}</button><button v-if="mode==='map'" class="membership-button secondary structure-preset-action" @click="presetsOpen=true">Presets</button><button v-if="mode==='map'" class="membership-button primary" :disabled="disabled||previewLoading" @click="mapKey++;refresh()">Recalculate map</button></header>
 <nav class="structure-tabs" aria-label="Bundle structure"><template v-if="mode==='cover'||mode==='numbering'"><button class="membership-button quiet" @click="presetsOpen=true">Preset</button><button :class="['membership-button',mode==='cover'?'primary':'quiet']" @click="selectMode('cover')">Cover &amp; index</button><button :class="['membership-button',mode==='numbering'?'primary':'quiet']" @click="selectMode('numbering')">Numbering</button><button class="membership-button quiet" @click="emit('policy','Output policy')">Output policy</button><button class="text-tool" @click="selectMode('map')">Back to page map</button></template><template v-else><button :class="['membership-button',mode==='map'?'primary':'quiet']" @click="selectMode('map')">Index &amp; page map</button><button :class="['membership-button',mode==='bookmarks'?'primary':'quiet']" @click="selectMode('bookmarks')">Bookmarks</button><button :class="['membership-button',mode==='volumes'?'primary':'quiet']" @click="selectMode('volumes')">Volume planning</button><button class="membership-button quiet" @click="selectMode('cover')">Cover &amp; index</button><button class="membership-button quiet" @click="selectMode('numbering')">Numbering</button></template><button class="membership-button quiet structure-membership" @click="emit('membership')">Bundle membership</button></nav>
 <p v-if="loading&&!settings" role="status">Loading bundle settings…</p><p v-if="error" role="alert" class="structure-error">{{error}} <button v-if="!settings" class="text-tool" @click="load()">Retry loading</button><button v-else class="text-tool" @click="load(true)">Reload saved settings (discard draft)</button></p><p v-if="notice" class="structure-notice" role="status">{{notice}}</p>
 <template v-if="settings">
  <ManualBookmarks v-if="mode==='bookmarks'||bookmarkDirty" v-show="mode==='bookmarks'" ref="bookmarksRef" :matter-id="matterId" :documents="documents" :refresh-key="refreshKey" :disabled="disabled||saving" :settings="settings" :preset="bookmarkPreset" @dirty-changed="bookmarkDirty=$event" @modified="emit('modified')"/>
  <div v-if="mode==='numbering'" class="numbering-workspace">
   <button class="membership-button secondary compact-numbering-toggle" :aria-expanded="drawer" @click="drawer=!drawer">Content numbering settings</button>
   <NumberingSettings v-model="settings.output_marks" :disabled="disabled||saving" :class="{'settings-open':drawer}" @keydown.esc="drawer=false"/>
   <NumberPlacementPreview class="structure-card" :matter-id="matterId" :settings="settings" :documents="documents" :refresh-key="refreshKey" :disabled="disabled"/>
  </div>
  <div v-else-if="mode==='cover'" class="cover-workspace">
   <button class="membership-button secondary compact-front-toggle" :aria-expanded="drawer" @click="drawer=!drawer"><SlidersHorizontal :size="16"/>Front-matter settings</button>
   <aside class="structure-card front-settings" :class="{'settings-open':drawer}"><h2>Front-matter settings</h2><fieldset :disabled="disabled||saving"><label>Court / heading<input v-model="settings.output_marks.cover_heading" maxlength="200" placeholder="Matter bundle"/></label><label>Matter reference<input v-model="settings.output_marks.cover_reference" maxlength="100" placeholder="Use matter case number"/></label><label>Bundle title<input v-model="settings.output_marks.cover_title" maxlength="200" placeholder="Document bundle"/></label><label>Volume front matter<select v-model="settings.output_marks.front_matter"><option value="index_only">Generated index only</option><option value="cover_index">Cover + generated index</option></select></label><h3>Index columns</h3><label class="structure-check"><input type="checkbox" checked disabled/>Document title</label><label class="structure-check"><input v-model="settings.output_marks.index_date" type="checkbox"/>Date</label><label class="structure-check"><input type="checkbox" checked disabled/>Printed page references</label><details><summary>Index density &amp; Part PDFs</summary><label>Index layout<select v-model="settings.output_marks.index_style"><option value="review">Review · spacious linked index</option><option value="compact">Compact</option><option value="readable">Readable</option></select></label><label class="structure-check"><input v-model="settings.output_marks.part_extracts_enabled" type="checkbox"/>Also create separate technical Part PDFs</label><p>Date columns use the readable row spacing. Titles and references are required.</p></details></fieldset><p>Case details stay with this matter. Presets retain only layout settings.</p></aside>
   <section class="structure-card generated-front"><header><h2>Generated preview</h2><span class="structure-badge"><Info :size="14"/>{{dirty?'Unsaved layout':'Saved layout'}} · {{preview?`Volume ${preview.selected_volume}`:'Pending'}}</span></header><div class="front-preview-pages"><p v-if="previewLoading" role="status">Rendering current cover and index…</p><p v-else-if="disabled" role="status">Preview paused while inputs are changing or the engine is unavailable.</p><p v-else-if="previewError" role="alert">{{previewError}} <button class="text-tool" @click="refresh">Retry preview</button></p><p v-else-if="preview&&!preview.volumes.length">Include documents in the bundle to generate its cover and index.</p><figure v-for="page in preview?.pages||[]" :key="page.kind"><img :src="page.image" :alt="`Generated ${page.kind}, volume ${preview?.selected_volume}, physical page ${page.physical_page}`"/><figcaption>{{page.kind==='cover'?'Cover':`Index ${preview?.selected_index_page} of ${preview?.volumes[(preview?.selected_volume||1)-1]?.index_pages}`}} · physical page {{page.physical_page}}</figcaption></figure></div><footer v-if="preview?.volumes.length"><span>{{preview.volumes[preview.selected_volume-1].cover_pages}} cover + {{preview.volumes[preview.selected_volume-1].index_pages}} index page(s) counted physically in this volume.</span><label>Volume<select v-model.number="volume"><option v-for="v in preview.volumes" :value="v.number" :key="v.number">{{v.number}}</option></select></label><button class="icon-btn" aria-label="Previous index page" :disabled="preview.selected_index_page<=1" @click="indexPage=preview.selected_index_page-1"><ChevronLeft :size="16"/></button><button class="icon-btn" aria-label="Next index page" :disabled="preview.selected_index_page>=preview.volumes[preview.selected_volume-1].index_pages" @click="indexPage=preview.selected_index_page+1"><ChevronRight :size="16"/></button></footer></section>
  </div>
  <div v-else-if="mode==='volumes'" class="structure-volume-grid"><section class="structure-card"><h2>Volume settings</h2><fieldset :disabled="disabled||saving"><label>Maximum pages per volume<input v-model.number="settings.max_pages_per_volume" type="number" min="2" max="2000"/></label><label class="structure-check"><input v-model="settings.keep_groups_intact" type="checkbox"/>Keep document groups together</label></fieldset><p>Includes generated cover, index and separator pages. Documents are never split automatically.</p><button class="membership-button secondary" :disabled="!dirty" @click="discard">Cancel changes</button></section><section class="structure-card"><h2>Current volume plan</h2><p v-if="previewLoading">Recalculating…</p><p v-if="previewError" role="alert">{{previewError}}</p><div v-for="v in preview?.volumes||[]" :key="v.number" class="volume-plan-row"><strong>Volume {{v.number}}</strong><span>{{v.page_count}} physical pages · {{v.cover_pages}} cover · {{v.index_pages}} index</span></div></section></div>
  <div v-else-if="mode==='bookmarks'" class="structure-bookmarks"><details class="bookmark-import"><summary>Import reviewed bookmarks from CSV / TSV</summary><slot name="import"/></details></div>
  <div v-else class="structure-map-grid"><aside class="structure-card structure-order"><slot name="order"/></aside><section class="structure-card structure-map"><slot name="map" :recalculate-key="mapKey"/></section></div>
  <div class="structure-bottom"><button v-if="dirty" class="membership-button secondary" :disabled="saving" @click="discard">Cancel changes</button><span v-if="dirty" role="status">Unsaved settings — apply before building</span><span v-else-if="settings.applied">Applied: {{settings.applied.name}} v{{settings.applied.version}} · {{overrides.length}} field override(s)</span><span v-else>Technical matter settings · no court approval</span><button v-if="mode!=='cover'" class="text-tool" @click="emit('build')">Continue to Build bundle</button></div>
  <details v-if="overrides.length" class="structure-overrides"><summary>Settings different from applied preset ({{overrides.length}})</summary><ul><li v-for="item in overrides" :key="item.field">{{item.label}}: {{displaySetting(item.baseline)}} → <strong>{{displaySetting(item.current)}}</strong></li></ul></details>
 </template>
 <BundlePresetDialog v-if="presetsOpen&&settings" :matter-id="matterId" :settings="settings" :dirty="dirty" :disabled="disabled" @close="presetsOpen=false" @applied="applied" @cover="presetsOpen=false;selectMode('cover')"/>
</section>
</template>
